"""matplotlib.scale — axis scale classes."""

import numpy as _np


class ScaleBase:
    """Base class for axis scales. Subclasses override ``get_transform``
    to return the data→display transform pair, and
    ``set_default_locators_and_formatters`` to wire up sensible tick
    locators/formatters when the user picks this scale."""

    name = None
    def __init__(self, axis=None, **kwargs):
        self.axis = axis

    def get_transform(self):
        """Default — identity transform. Subclasses override."""
        from matplotlib.transforms import IdentityTransform
        return IdentityTransform()

    def set_default_locators_and_formatters(self, axis):
        from matplotlib.ticker import AutoLocator, AutoMinorLocator, ScalarFormatter
        if axis is None: return
        try:
            axis.set_major_locator(AutoLocator())
            axis.set_minor_locator(AutoMinorLocator())
            axis.set_major_formatter(ScalarFormatter())
        except Exception:
            pass

    def limit_range_for_scale(self, vmin, vmax, minpos):
        return (vmin, vmax)


class LinearScale(ScaleBase):
    name = 'linear'

    def get_transform(self):
        from matplotlib.transforms import IdentityTransform
        return IdentityTransform()


class LogScale(ScaleBase):
    name = 'log'

    def __init__(self, axis=None, *, base=10, subs=None, nonpositive='clip'):
        super().__init__(axis)
        self.base = float(base)
        self.subs = subs
        self.nonpositive = nonpositive

    def get_transform(self):
        return LogTransform(base=self.base, nonpositive=self.nonpositive)

    def set_default_locators_and_formatters(self, axis):
        from matplotlib.ticker import LogLocator, LogFormatterSciNotation
        if axis is None: return
        try:
            axis.set_major_locator(LogLocator(base=self.base, subs=(1.0,)))
            axis.set_minor_locator(LogLocator(base=self.base, subs='auto'))
            axis.set_major_formatter(LogFormatterSciNotation(base=self.base))
        except Exception:
            pass

    def limit_range_for_scale(self, vmin, vmax, minpos):
        # Log scale needs vmin > 0.
        if vmin <= 0:
            vmin = minpos if (minpos is not None and minpos > 0) else 1e-300
        if vmax <= 0:
            vmax = minpos * 10 if (minpos and minpos > 0) else 1.0
        return (vmin, vmax)


class SymmetricalLogScale(ScaleBase):
    name = 'symlog'

    def __init__(self, axis=None, *, base=10, linthresh=2, subs=None, linscale=1):
        super().__init__(axis)
        self.base = float(base)
        self.linthresh = float(linthresh)
        self.subs = subs
        self.linscale = float(linscale)

    def get_transform(self):
        return SymmetricalLogTransform(base=self.base,
                                         linthresh=self.linthresh,
                                         linscale=self.linscale)


class LogitScale(ScaleBase):
    name = 'logit'

    def __init__(self, axis=None, *, nonpositive='mask', one_half='\\frac{1}{2}',
                 use_overline=False):
        super().__init__(axis)
        self.nonpositive = nonpositive
        self.one_half = one_half
        self.use_overline = use_overline

    def get_transform(self):
        return LogitTransform(nonpositive=self.nonpositive)


class FuncScale(ScaleBase):
    name = 'function'

    def __init__(self, axis, functions):
        super().__init__(axis)
        self._forward, self._inverse = functions

    def get_transform(self):
        return FuncTransform(self._forward, self._inverse)


class AsinhScale(ScaleBase):
    name = 'asinh'

    def __init__(self, axis=None, *, linear_width=1.0, base=10, subs='auto', **kwargs):
        super().__init__(axis)
        self.linear_width = float(linear_width)
        self.base = float(base)
        self.subs = subs

    def get_transform(self):
        return AsinhTransform(linear_width=self.linear_width)


# Scale registry
_scale_mapping = {
    'linear': LinearScale,
    'log': LogScale,
    'symlog': SymmetricalLogScale,
    'logit': LogitScale,
    'function': FuncScale,
    'asinh': AsinhScale,
}


def scale_factory(scale, axis, **kwargs):
    if scale in _scale_mapping:
        return _scale_mapping[scale](axis, **kwargs)
    raise ValueError(f"Unknown scale: {scale!r}")


def get_scale_names():
    return list(_scale_mapping.keys())


def register_scale(scale_class):
    _scale_mapping[scale_class.name] = scale_class


# ─── Added: missing public Transform classes from upstream scale.py ───
#
# Each *Transform here mirrors the math of its parent Scale. They expose
# the standard transform interface (``transform(x)`` / ``inverted()``) so
# that code grabbing ``scale.get_transform()`` from upstream still works
# against the shim.


class _ScaleTransform:
    """Common base: scalar/array forward+inverse pair with no shape change."""
    input_dims = 1
    output_dims = 1
    is_affine = False
    is_separable = True

    def transform(self, values):
        return self.transform_non_affine(values)

    def transform_non_affine(self, values):
        return _np.asarray(values, dtype=float)

    def transform_affine(self, values):
        return _np.asarray(values, dtype=float)

    def get_matrix(self):
        return _np.eye(3)

    def inverted(self):
        raise NotImplementedError


class LogTransform(_ScaleTransform):
    """``y = log(x) / log(base)`` — the forward transform for a log scale.

    Non-positive inputs are either clipped to a tiny positive number or
    masked (NaN), matching upstream's ``nonpositive`` option.
    """

    def __init__(self, base=10, nonpositive='clip'):
        self.base = float(base)
        self._log_base = _np.log(self.base)
        self.nonpositive = nonpositive

    def transform_non_affine(self, a):
        a = _np.asarray(a, dtype=float)
        if self.nonpositive == 'mask':
            out = _np.where(a > 0, a, _np.nan)
        else:
            # 'clip' — replace non-positives with tiny positive value.
            out = _np.where(a > 0, a, 1e-300)
        return _np.log(out) / self._log_base

    def inverted(self):
        return InvertedLogTransform(self.base)


class InvertedLogTransform(_ScaleTransform):
    """Inverse of :class:`LogTransform`: ``x = base ** y``."""

    def __init__(self, base=10):
        self.base = float(base)

    def transform_non_affine(self, a):
        return _np.power(self.base, _np.asarray(a, dtype=float))

    def inverted(self):
        return LogTransform(self.base)


class SymmetricalLogTransform(_ScaleTransform):
    """Forward symmetric-log: linear inside ``[-linthresh, linthresh]``,
    log outside. Continuous and smooth at the boundary by construction.

    ``y = sign(x) * (linthresh * linscale + linthresh * log(|x| / linthresh) / log(base))``
    for ``|x| > linthresh``, otherwise ``y = x * linscale``.
    """

    def __init__(self, base=10, linthresh=2.0, linscale=1.0):
        self.base = float(base)
        self.linthresh = float(linthresh)
        self.linscale = float(linscale)
        self._log_base = _np.log(self.base)
        # Continuity coefficient so the two pieces meet smoothly.
        self._linscale_adj = linscale / (1.0 - 1.0 / self.base)

    def transform_non_affine(self, a):
        a = _np.asarray(a, dtype=float)
        sign = _np.sign(a)
        abs_a = _np.abs(a)
        log_region = abs_a > self.linthresh
        out = a * self._linscale_adj
        out_log = sign * self.linthresh * (
            self._linscale_adj
            + _np.log(_np.where(log_region, abs_a, self.linthresh) / self.linthresh)
            / self._log_base)
        return _np.where(log_region, out_log, out)

    def inverted(self):
        return InvertedSymmetricalLogTransform(
            self.base, self.linthresh, self.linscale)


class InvertedSymmetricalLogTransform(_ScaleTransform):
    """Inverse of :class:`SymmetricalLogTransform`."""

    def __init__(self, base=10, linthresh=2.0, linscale=1.0):
        self.base = float(base)
        self.linthresh = float(linthresh)
        self.linscale = float(linscale)
        self._log_base = _np.log(self.base)
        self._linscale_adj = linscale / (1.0 - 1.0 / self.base)
        self._inv_linthresh = self.linthresh * self._linscale_adj

    def transform_non_affine(self, a):
        a = _np.asarray(a, dtype=float)
        sign = _np.sign(a)
        abs_a = _np.abs(a)
        log_region = abs_a > self._inv_linthresh
        out_lin = a / self._linscale_adj
        out_log = sign * self.linthresh * _np.power(
            self.base,
            (_np.where(log_region, abs_a, self._inv_linthresh)
             / self.linthresh - self._linscale_adj))
        return _np.where(log_region, out_log, out_lin)

    def inverted(self):
        return SymmetricalLogTransform(
            self.base, self.linthresh, self.linscale)


class LogitTransform(_ScaleTransform):
    """Forward logit: ``y = log(p / (1 - p))`` for ``p`` in ``(0, 1)``.
    Values outside the open interval are either clipped to ``[eps, 1-eps]``
    or masked, matching upstream's ``nonpositive`` parameter.
    """

    def __init__(self, nonpositive='mask'):
        self.nonpositive = nonpositive

    def transform_non_affine(self, a):
        a = _np.asarray(a, dtype=float)
        eps = _np.finfo(float).eps
        if self.nonpositive == 'mask':
            a = _np.where((a > 0) & (a < 1), a, _np.nan)
        else:
            a = _np.clip(a, eps, 1 - eps)
        return _np.log(a / (1 - a))

    def inverted(self):
        return LogisticTransform(self.nonpositive)


class LogisticTransform(_ScaleTransform):
    """Inverse logit (sigmoid): ``p = 1 / (1 + exp(-y))``."""

    def __init__(self, nonpositive='mask'):
        self.nonpositive = nonpositive

    def transform_non_affine(self, a):
        a = _np.asarray(a, dtype=float)
        # Use the numerically stable form.
        return 1.0 / (1.0 + _np.exp(-a))

    def inverted(self):
        return LogitTransform(self.nonpositive)


class AsinhTransform(_ScaleTransform):
    """Forward asinh scaling: ``y = arcsinh(x / linear_width)``.
    Linear near zero, logarithmic at large ``|x|``, and naturally handles
    negative values without needing the symmetric-log piecewise definition.
    """

    def __init__(self, linear_width=1.0):
        self.linear_width = float(linear_width)

    def transform_non_affine(self, a):
        return _np.arcsinh(_np.asarray(a, dtype=float) / self.linear_width)

    def inverted(self):
        return InvertedAsinhTransform(self.linear_width)


class InvertedAsinhTransform(_ScaleTransform):
    """Inverse asinh: ``x = linear_width * sinh(y)``."""

    def __init__(self, linear_width=1.0):
        self.linear_width = float(linear_width)

    def transform_non_affine(self, a):
        return self.linear_width * _np.sinh(_np.asarray(a, dtype=float))

    def inverted(self):
        return AsinhTransform(self.linear_width)


class FuncTransform(_ScaleTransform):
    """Caller-supplied forward + inverse pair. Mirrors upstream's
    :class:`matplotlib.scale.FuncTransform` used by :class:`FuncScale`.
    """

    def __init__(self, forward, inverse):
        self._forward = forward
        self._inverse = inverse

    def transform_non_affine(self, a):
        return _np.asarray(self._forward(a), dtype=float)

    def inverted(self):
        return FuncTransform(self._inverse, self._forward)


class FuncScaleLog(ScaleBase):
    """A FuncScale whose output is then log-scaled. Used when the
    intermediate quantity is non-linear but the resulting axis still
    needs the readability of a log scale.
    """
    name = 'functionlog'

    def __init__(self, axis, functions, base=10):
        forward, inverse = functions
        self._forward = forward
        self._inverse = inverse
        self.base = base
        # Composition: log_base(forward(x))
        log_transform = LogTransform(base)
        func_transform = FuncTransform(forward, inverse)
        # Store both; get_transform returns a tiny composite below.
        self._func = func_transform
        self._log = log_transform

    def get_transform(self):
        # Composition is applied left-to-right: func then log.
        outer = self  # capture

        class _Composite(_ScaleTransform):
            def transform_non_affine(_self, a):
                return outer._log.transform_non_affine(
                    outer._func.transform_non_affine(a))

            def inverted(_self):
                # Reverse order: log⁻¹ then func⁻¹.
                inv_log = outer._log.inverted()
                inv_func = outer._func.inverted()

                class _Inv(_ScaleTransform):
                    def transform_non_affine(__self, a):
                        return inv_func.transform_non_affine(
                            inv_log.transform_non_affine(a))

                    def inverted(__self):
                        return _Composite()
                return _Inv()
        return _Composite()


# Register the new scale.
_scale_mapping['functionlog'] = FuncScaleLog


# Per-class default tick-multiplier list used by AsinhScale when subs='auto'.
AsinhScale.auto_tick_multipliers = (1, 3, 5)
# `base` / `linthresh` / `linscale` / `linear_width` are instance attrs
# set in each Scale's __init__; no class-level stubs needed (instance
# attrs shadow class-level lookups anyway).
